package com.gathin.tvhome;

import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Optional first-run help: a local wizard or a bounded AI draft, always reviewed before a save. */
public final class GuidedSetupActivity extends Activity {
    static final int IMPORT=4801,EXPORT=4802;
    private static final String PROMPT="Help me set up DV Freedom Launcher. Ask which look I prefer (glass, clean, cinema or legacy), top/middle/bottom apps, favorite app order, readable text size and idle view. Return only a JSON object with schema:1, name, settings and optional favorites. Settings allow experience, position, columns (2–8), text (auto/light/dark), textSize (85/100/110/120), names (theme/all/selected/hidden), strongFocus (boolean), idleSeconds (0/30/60/120). Favorite entries must use exact app package IDs from an inventory I choose to share; omit favorites if no inventory is supplied. Do not invent apps, commands, URLs, permissions, network settings, accounts or API keys. Keep everything offline and propose no paid calls. I will review the draft in the launcher before applying it.";
    private LinearLayout body,footer;private TextView title,detail;private Typeface font;private int step,focusRow,renderedStep=-1;
    private Config config;private String profile,beforeRevision;private Map<String,?> before;private List<HomeCategories.App> catalog;private final List<String> chosen=new ArrayList<>();private final Map<String,Object> settings=new LinkedHashMap<>();private String name="My Home";private boolean newProfile=true;private byte[] export;
    @Override protected void attachBaseContext(Context c){super.attachBaseContext(LauncherLocale.wrap(c));}
    @Override protected void onCreate(Bundle saved){super.onCreate(saved);ProductFeatures.init(this);config=Config.load(this);profile=ProfileStore.id();before=ProfileStore.preferences(this).getAll();catalog=HomeCategories.catalog(this,config);chosen.addAll(SetupProposal.visibleDefaults(DesktopLayout.favorites(config,Order.load(Order.file(this))),installed()));settings.put("experience",ExperienceChoice.saved(this));String p=PlacementSession.selected(this);settings.put("position",AppPlacement.valid(p)?p:"top");settings.put("columns",config.columns);android.content.SharedPreferences prefs=ProfileStore.preferences(this);settings.put("text",prefs.getBoolean(HomePolish.HEADER,false)?new String[]{"auto","light","dark"}[Math.max(0,Math.min(2,prefs.getInt(HomePolish.INK,0)))]:"auto");settings.put("names",new String[]{"theme","all","selected","hidden"}[Math.max(0,Math.min(3,prefs.getInt(HomePolish.NAMES,0)))]);settings.put("strongFocus",prefs.getBoolean(TileSpacing.FOCUS,false));settings.put("idleSeconds",prefs.getInt(HomePolish.IDLE,0));
        font=((TextView)getLayoutInflater().inflate(R.layout.item_app,null).findViewById(R.id.name)).getTypeface();
        try{beforeRevision=SetupTransfer.revision(this);}catch(Exception unavailable){beforeRevision="";}
        if(saved==null&&getIntent().hasExtra("staged_setup_token"))try{read(SetupTransfer.take(this,getIntent().getStringExtra("staged_setup_token")));step=3;}catch(Exception invalid){Toast.makeText(this,invalid.getMessage(),Toast.LENGTH_LONG).show();finish();return;}
        if(saved!=null){profile=saved.getString("origin_profile",profile);beforeRevision=saved.getString("origin_revision","");}
        if(saved!=null)try{read(new JSONObject(saved.getString("draft")));step=saved.getInt("step",0);newProfile=saved.getBoolean("newProfile",true);}catch(Exception bad){step=0;}
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(42),dp(28),dp(42),dp(20));root.setBackgroundColor(0xff111820);setContentView(root);title=text("",30);root.addView(title);detail=text("",16);detail.setTextColor(0xffc7d3e2);root.addView(detail);ScrollView scroll=new ScrollView(this);scroll.setFocusable(false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,0,1);sp.topMargin=dp(18);root.addView(scroll,sp);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);footer=new LinearLayout(this);footer.setGravity(Gravity.END);root.addView(footer);render();
    }
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(0xfff5f7fa);v.setTypeface(font);return v;}
    private TextView action(LinearLayout host,String label,Runnable run){TextView v=text(label,18);v.setPadding(dp(18),dp(12),dp(18),dp(12));v.setMinHeight(dp(50));v.setBackgroundResource(R.drawable.settings_choice_bg);v.setFocusable(true);v.setClickable(true);v.setOnFocusChangeListener((x,on)->{if(on&&host==body)focusRow=body.indexOfChild(v);});v.setOnClickListener(x->run.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(host==footer?-2:-1,-2);p.bottomMargin=dp(7);if(host==footer)p.leftMargin=dp(12);host.addView(v,p);return v;}
    private void choice(String label,String key,String[] labels,Object[] values){int at=Arrays.asList(values).indexOf(settings.get(key));action(body,label+"  ·  "+(at<0?"Keep current":labels[at]),()->new AlertDialog.Builder(this).setTitle(label).setSingleChoiceItems(labels,at,(d,n)->{if(values[n]==null)settings.remove(key);else settings.put(key,values[n]);d.dismiss();render();}).setNegativeButton(android.R.string.cancel,null).show());}
    private void render(){if(renderedStep!=step){focusRow=0;renderedStep=step;}int restore=focusRow;body.removeAllViews();footer.removeAllViews();title.setText(step==0?"Set up your Home":step==1?"Choose your apps":step==2?"Make it comfortable":"Review your setup");detail.setText(step==0?"Use the remote, or import a draft from your AI assistant. Skip leaves Home unchanged.":step==1?"Your existing order stays first. Newly selected apps are added at the end.":step==2?"These choices affect this launcher, including its text and app row.":"Nothing is saved until you choose Apply. Streaming accounts and TV system settings stay with their own apps.");
        if(step==0){choice("Home experience","experience",new String[]{"Current layout","Freedom Glass","Freedom Clean","Freedom Cinema"},new Object[]{"legacy","glass","clean","cinema"});action(body,"AI setup help",this::aiHelp);action(body,"Import AI setup draft",this::importDraft);}
        else if(step==1){for(HomeCategories.App app:catalog){boolean on=chosen.contains(app.pkg);action(body,(on?"✓  ":"     ")+app.label,()->{if(chosen.contains(app.pkg))chosen.remove(app.pkg);else if(chosen.size()<32)chosen.add(app.pkg);else Toast.makeText(this,"Choose up to 32 apps",Toast.LENGTH_SHORT).show();render();});}}
        else if(step==2){choice("App position","position",new String[]{"Top","Middle","Bottom"},new Object[]{"top","middle","bottom"});choice("Apps per row","columns",new String[]{"4","5","6","7","8"},new Object[]{4,5,6,7,8});choice("Text color","text",new String[]{"Automatic","Light","Dark"},new Object[]{"auto","light","dark"});choice("Text size","textSize",new String[]{"Keep current sizes","Compact","Normal","Larger","Largest"},new Object[]{null,85,100,110,120});choice("Strong focus outline","strongFocus",new String[]{"Off","On"},new Object[]{false,true});choice("App names","names",new String[]{"Theme default","All apps","Selected app","Hidden"},new Object[]{"theme","all","selected","hidden"});choice("Quiet idle view","idleSeconds",new String[]{"Off","30 seconds","1 minute","2 minutes"},new Object[]{0,30,60,120});}
        else{try{SetupProposal proposal=proposal();action(body,"Save to  ·  "+(newProfile?"New profile (recommended)":"Current profile"),()->{newProfile=!newProfile;render();});if(newProfile)action(body,"Profile name  ·  "+name,()->SetupUi.name(this,R.string.setup_name,name,s->{name=s;render();}));StringBuilder summary=new StringBuilder("Choices to apply:\n");for(Map.Entry<String,Object> e:proposal.values.entrySet())if(!Objects.equals(before.get(e.getKey()),e.getValue()))summary.append(storedLabel(e.getKey())).append(": ").append(display(e.getKey(),before.get(e.getKey()))).append(" → ").append(display(e.getKey(),e.getValue())).append('\n');summary.append("\nApps in order:\n");for(int i=0;i<chosen.size();i++){if(i>0)summary.append("   →   ");summary.append(appName(chosen.get(i)));}summary.append("\n\nOther saved choices stay as they are.");TextView review=text(summary.toString(),17);review.setLineSpacing(dp(4),1);body.addView(review);}catch(Exception bad){body.addView(text(bad.getMessage(),18));}}
        action(footer,"Cancel",this::finish);if(step>0)action(footer,"Back",()->{step--;render();});action(footer,step==3?"Apply setup":"Next",()->{if(step==3)apply();else if(step==1&&chosen.isEmpty())Toast.makeText(this,"Choose at least one app",Toast.LENGTH_SHORT).show();else{step++;render();}});if(body.getChildCount()>0)body.getChildAt(Math.min(restore,body.getChildCount()-1)).requestFocus();
    }
    private String display(String key,Object value){if(value==null)return "Theme default";if(key.equals(ExperiencePolicy.KEY))return ExperiencePolicy.name(String.valueOf(value));if(key.equals(HomePolish.INK))return new String[]{"Automatic","Light","Dark"}[((Number)value).intValue()];if(key.equals(HomePolish.NAMES))return new String[]{"Theme default","All apps","Selected app","Hidden"}[((Number)value).intValue()];if(value instanceof Boolean)return (Boolean)value?"On":"Off";if(key.equals(HomeAppearance.KEY))return String.valueOf(value).replace("v1,","").replace(",","% / ")+"%";return String.valueOf(value);}
    private String storedLabel(String key){if(key.equals(ExperiencePolicy.KEY))return "Home experience";if(key.equals(AppPlacement.KEY))return "App position";if(key.equals(HomeAppearance.KEY))return "Text sizes";if(key.equals(HomePolish.HEADER))return "Adaptive text";if(key.equals(HomePolish.INK))return "Text color";if(key.equals(HomePolish.NAMES))return "App names";if(key.equals(TileSpacing.FOCUS))return "Strong focus outline";if(key.equals(HomePolish.IDLE))return "Quiet idle";return label(key);}
    private String label(String key){if(key.equals("experience"))return "Home experience";if(key.equals("position"))return "App position";if(key.equals("textSize"))return "Text size (%)";if(key.equals("idleSeconds"))return "Quiet idle (seconds)";return key;}
    private String appName(String p){for(HomeCategories.App a:catalog)if(a.pkg.equals(p))return a.label;return p;}
    private JSONObject json()throws Exception{return new JSONObject().put("schema",1).put("name",name).put("settings",new JSONObject(settings)).put("favorites",new JSONArray(chosen));}
    private SetupProposal proposal()throws Exception{return new SetupProposal(ProfileStore.object(json()),installed());}
    private Set<String> installed(){Set<String> out=new HashSet<>();for(HomeCategories.App a:catalog)out.add(a.pkg);return out;}
    private void read(JSONObject json)throws Exception{SetupProposal p=new SetupProposal(ProfileStore.object(json),installed());name=p.name;settings.clear();JSONObject values=json.getJSONObject("settings");for(Iterator<String> it=values.keys();it.hasNext();){String k=it.next();settings.put(k,values.get(k));}if(p.favorites!=null){chosen.clear();chosen.addAll(p.favorites);}}
    private void apply(){try{Config.load(this);if(!profile.equals(ProfileStore.id())||!before.equals(ProfileStore.preferences(this).getAll())||!beforeRevision.equals(SetupTransfer.revision(this)))throw new IllegalStateException("Home changed while this draft was open. Cancel and review it again.");if(!LauncherLock.require(this,this::apply))return;catalog=HomeCategories.catalog(this,config);SetupProposal proposal=proposal();Map<String,Object> values=new HashMap<>(proposal.values);JSONObject layout=new JSONObject(DesktopLayout.capture(this,config));JSONObject data=layout.getJSONObject("layout");data.put("favorites",new JSONArray(chosen));JSONArray hidden=data.getJSONArray("hidden"),kept=new JSONArray();for(int i=0;i<hidden.length();i++)if(!chosen.contains(hidden.getString(i)))kept.put(hidden.getString(i));data.put("hidden",kept);layout.put("dock",new JSONArray(chosen));values.put(DesktopLayout.STATE,layout.toString());SetupValues.validate(values);
            if(newProfile){if(name.equalsIgnoreCase(getString(R.string.profile_current)))throw new IllegalArgumentException("Choose a different profile name");List<LocalProfiles.Profile> rows=new ArrayList<>(ProfileSetup.read(this));if(ProfileStore.read(this).size()>=16)throw new IllegalArgumentException("Maximum 16 profiles");for(LocalProfiles.Profile row:ProfileStore.read(this))if(row.name.equalsIgnoreCase(name))throw new IllegalArgumentException("That profile name already exists");String id="local_"+UUID.randomUUID();layout.put("orderStamp",DesktopLayout.orderStamp(new File(getFilesDir(),LocalProfiles.filename(id,Order.FILE_NAME))));values.put(DesktopLayout.STATE,layout.toString());Map<String,Object> all=SetupStore.capture(this);all.putAll(values);String signature=ProfileStore.preferences(this).getString(Config.THEME_SIGNATURE_KEY,null);if(signature!=null)all.put(Config.THEME_SIGNATURE_KEY,signature);rows.add(new LocalProfiles.Profile(id,name,chosen,config.hiddenApps,(Integer)values.getOrDefault("columns",config.columns)));Map<String,Object> writes=new HashMap<>();for(Map.Entry<String,Object> e:all.entrySet())writes.put(LocalProfiles.key(id,e.getKey()),e.getValue());writes.put(ProfileSetup.CREATED,ProfileSetup.encode(rows));writes.put(ProfileSetup.ENABLED,true);writes.put(ProfileStore.ACTIVE,id);android.content.SharedPreferences global=ProfileSetup.global(this);writes.put(Config.SETTINGS_REVISION_KEY,global.getLong(Config.SETTINGS_REVISION_KEY,0)+1);if(!SetupValues.commit(global,writes))throw new IllegalStateException("Could not create this setup");}
            else{ProductFeatures.beforeChange(this,"Apply guided/AI setup");values.put(Config.SETTINGS_REVISION_KEY,ProfileStore.preferences(this).getLong(Config.SETTINGS_REVISION_KEY,0)+1);if(!SetupValues.commit(ProfileStore.preferences(this),values))throw new IllegalStateException("Could not apply this setup");}Config.load(this);ExperienceChoice.home(this);finish();
        }catch(Exception failed){new AlertDialog.Builder(this).setTitle("Setup not applied").setMessage(failed.getMessage()).setPositiveButton(android.R.string.ok,null).show();}}
    private void aiHelp(){new AlertDialog.Builder(this).setTitle("Set up with your AI assistant").setMessage("Use your existing AI assistant on a phone or computer. Share only the app inventory you choose to export, then ask for a setup draft. Import its JSON here and review every choice.\n\nThe launcher sends nothing to an AI provider and stores no API key.\n\nGuide: github.com/DVOpenLabs/cleanyourtv → product/AI-SETUP.md").setNeutralButton("Copy prompt",(d,w)->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("DV Freedom setup",PROMPT));Toast.makeText(this,"Prompt copied on this device",Toast.LENGTH_LONG).show();}).setNegativeButton("Close",null).setPositiveButton("Export template",(d,w)->exportTemplate()).show();}
    private void importDraft(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),IMPORT);}catch(Exception noPicker){Toast.makeText(this,"No file picker is available. Use the desktop setup tool.",Toast.LENGTH_LONG).show();}}
    private void exportTemplate(){try{JSONArray apps=new JSONArray();for(HomeCategories.App a:catalog)apps.put(new JSONObject().put("package",a.pkg).put("name",a.label));export=new JSONObject().put("prompt",PROMPT).put("draft",json()).put("apps",apps).toString(2).getBytes(StandardCharsets.UTF_8);startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"freedom-setup-template.json"),EXPORT);}catch(Exception noPicker){Toast.makeText(this,"No file picker is available. The setup guide includes a template.",Toast.LENGTH_LONG).show();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;try{if(request==IMPORT){try(InputStream in=getContentResolver().openInputStream(data.getData())){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>SetupProposal.MAX_BYTES)throw new IllegalArgumentException("Setup draft is too large");bytes.write(b,0,n);}String raw=bytes.toString("UTF-8");ThemeArchive.validateJsonObject(raw);read(new JSONObject(raw));step=3;render();}}else if(request==EXPORT&&export!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(export);}export=null;Toast.makeText(this,"Setup template exported. Share it only with an assistant you choose.",Toast.LENGTH_LONG).show();}}catch(Exception bad){new AlertDialog.Builder(this).setTitle("Draft not imported").setMessage(bad.getMessage()).setPositiveButton(android.R.string.ok,null).show();}}
    @Override public void onBackPressed(){if(step>0){step--;render();}else finish();}
    @Override protected void onResume(){super.onResume();}
    @Override protected void onSaveInstanceState(Bundle out){try{out.putString("draft",json().toString());out.putInt("step",step);out.putBoolean("newProfile",newProfile);out.putString("origin_profile",profile);out.putString("origin_revision",beforeRevision);}catch(Exception ignored){}super.onSaveInstanceState(out);}
}
